<"'!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="description" content="A little space for your next big idea. Find the right Marginalia plan for your notes, projects, and team.">
  <meta name="theme-color" content="#faf9f6">
  <title>Pricing — Marginalia</title>
  <style>
    :root { --paper: #faf9f6; --ink: #292b25; --muted: #73746b; --line: #e2e2d9; --accent: #b94d2d; --accent-dark: #963a20; --green: #54684f; }
    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; scroll-padding-top: 24px; }
    body { margin: 0; background: var(--paper); color: var(--ink); font-family: "Inter", "Segoe UI", Arial, sans-serif; font-size: 14px; -webkit-font-smoothing: antialiased; }
    button, a, summary { -webkit-tap-highlight-color: transparent; }
    a { color: inherit; text-decoration: none; }
    button { font: inherit; }
    a:focus-visible, button:focus-visible, summary:focus-visible { outline: 3px solid var(--accent); outline-offset: 5px; }
    .wrap { width: min(1100px, calc(100% - 64px)); margin-inline: auto; }
    .icon { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; flex-shrink: 0; }
    .svg-library { position: absolute; width: 0; height: 0; overflow: hidden; }
    .nav { height: 94px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--line); gap: 32px; }
    .logo { display: inline-flex; align-items: center; gap: 10px; font-family: Georgia, "Times New Roman", serif; font-size: 25px; letter-spacing: -.8px; }
    .logo .icon { color: var(--accent); width: 27px; height: 29px; stroke-width: 1.65; }
    .nav-links, .nav-actions { display: flex; align-items: center; gap: 30px; }
    .nav-links { margin-left: 50px; font-size: 13px; color: var(--muted); }
    .nav-links a:hover, .nav-actions > a:first-child:hover { color: var(--accent); }
    .nav-links [aria-current] { color: var(--ink); }
    .nav-actions { font-size: 13px; gap: 23px; }
    .nav-signup { padding: 11px 17px; border: 1px solid #c9cbc0; border-radius: 5px; transition: background .2s; }
    .nav-signup:hover { background: #eeeee7; }
    .hero { text-align: center; padding: 65px 0 35px; }
    .eyebrow { display: block; color: var(--accent); font-size: 10px; font-weight: 650; letter-spacing: 2px; text-transform: uppercase; }
    h1 { margin: 21px 0 20px; font-family: Georgia, "Times New Roman", serif; font-weight: 400; font-size: clamp(42px, 5vw, 62px); line-height: 1.08; letter-spacing: -2.5px; }
    h1 em { font-weight: 400; color: var(--accent); }
    .hero p { margin: 0; color: var(--muted); font-size: 14px; line-height: 1.8; }
    .billing { display: flex; justify-content: center; align-items: center; margin-top: 29px; gap: 12px; }
    .toggle { padding: 4px; display: inline-flex; background: #eeeee7; border: 1px solid #e5e5dc; border-radius: 7px; }
    .toggle button { border: 0; border-radius: 4px; padding: 9px 18px; color: var(--muted); background: transparent; cursor: pointer; font-size: 12px; transition: background .2s, color .2s; }
    .toggle button[aria-pressed="true"] { background: #fff; color: var(--ink); box-shadow: 0 1px 3px #292b2510; }
    .saving { font-size: 10px; font-weight: 600; color: var(--green); display: flex; align-items: center; gap: 6px; }
    .saving .icon { width: 22px; }
    .plans { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; padding-top: 8px; }
    .plan { border: 1px solid var(--line); border-radius: 9px; background: #fffefa; padding: 27px 28px 26px; display: flex; flex-direction: column; }
    .plan.popular { border-color: #c96b4d; background: #fbf5ef; box-shadow: 0 0 0 1px #c96b4d; }
    .plan-top { display: flex; align-items: center; justify-content: space-between; min-height: 25px; gap: 8px; }
    .plan-name { display: flex; align-items: center; gap: 10px; }
    .plan-name .icon { color: var(--muted); width: 19px; height: 19px; }
    .popular .plan-name .icon { color: var(--accent); }
    .plan h2 { margin: 0; font-size: 17px; font-weight: 600; letter-spacing: -.4px; }
    .badge { font-size: 9px; font-weight: 600; color: var(--accent); background: #f4e5da; border-radius: 4px; padding: 6px 8px; white-space: nowrap; }
    .desc { margin: 11px 0 23px; color: var(--muted); font-size: 12px; line-height: 1.6; }
    .price { display: flex; align-items: baseline; gap: 6px; min-height: 54px; letter-spacing: -2px; font-size: 48px; line-height: 1.1; font-weight: 500; }
    .price small { color: var(--muted); font-size: 12px; font-weight: 400; letter-spacing: 0; }
    .billing-note { margin: 5px 0 22px; min-height: 15px; font-size: 11px; color: var(--muted); }
    .btn { display: flex; justify-content: center; align-items: center; gap: 12px; min-height: 42px; border: 1px solid #cdcec3; border-radius: 5px; font-size: 12px; font-weight: 600; transition: background .2s, border-color .2s; }
    .btn:hover { background: #edeee6; border-color: #a4a79a; }
    .btn .icon { width: 15px; height: 15px; }
    .popular .btn { color: #fff; border-color: var(--accent); background: var(--accent); }
    .popular .btn:hover { background: var(--accent-dark); border-color: var(--accent-dark); }
    .feature-label { font-size: 10px; font-weight: 600; margin: 26px 0 14px; padding-top: 22px; border-top: 1px solid var(--line); letter-spacing: .2px; }
    .plan ul { margin: 0; padding: 0; list-style: none; display: grid; gap: 14px; }
    .plan li { display: flex; align-items: center; gap: 10px; font-size: 12px; line-height: 1.4; }
    .plan li .icon { width: 14px; height: 14px; stroke-width: 1.7; color: var(--green); }
    .plan li.unavailable { color: #96978c; }
    .plan li.unavailable .icon { color: #aaa99f; }
    .reassurance { display: flex; align-items: center; justify-content: center; gap: 7px; margin: 23px 0 0; font-size: 11px; color: var(--muted); }
    .reassurance .icon { width: 13px; height: 13px; }
    .features { margin-top: 66px; padding: 35px 0 38px; border-block: 1px solid var(--line); }
    .section-kicker { margin: 0 0 29px; text-align: center; font-weight: 500; font-size: 10px; letter-spacing: 1.8px; text-transform: uppercase; color: var(--muted); }
    .grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 42px; }
    .feature { display: flex; gap: 14px; }
    .feature > .icon { color: var(--green); width: 22px; height: 22px; margin-top: 1px; }
    .feature h3 { margin: 0 0 8px; font-size: 13px; font-weight: 600; }
    .feature p { margin: 0; color: var(--muted); font-size: 12px; line-height: 1.8; max-width: 250px; }
    .faq { padding: 65px 0 70px; display: grid; grid-template-columns: 1fr 1.6fr; gap: 80px; }
    .faq h2 { font-family: Georgia, "Times New Roman", serif; font-size: 32px; font-weight: 400; letter-spacing: -1px; line-height: 1.2; margin: 13px 0; }
    .faq-intro p { color: var(--muted); font-size: 12px; line-height: 1.7; margin: 0; }
    details { border-bottom: 1px solid var(--line); }
    summary { padding: 19px 0; display: flex; align-items: center; justify-content: space-between; gap: 20px; list-style: none; font-size: 13px; font-weight: 500; cursor: pointer; }
    details:first-child summary { padding-top: 0; }
    summary::-webkit-details-marker { display: none; }
    summary::after { content: "+"; color: var(--muted); font-size: 19px; font-weight: 400; line-height: 1; }
    details[open] summary::after { content: "−"; }
    details p { margin: -3px 24px 20px 0; color: var(--muted); font-size: 12px; line-height: 1.8; }
    footer { border-top: 1px solid var(--line); }
    .footer-inner { min-height: 85px; display: flex; align-items: center; justify-content: space-between; gap: 20px; }
    footer .logo { font-size: 20px; }
    footer .logo .icon { width: 22px; height: 24px; }
    footer p { color: var(--muted); font-size: 10px; }
    .footer-note { color: var(--muted); font-family: Georgia, "Times New Roman", serif; font-size: 13px; font-style: italic; }
    @media (min-width: 1500px) { .hero { padding-top: 78px; } }
    @media (max-width: 900px) { .wrap { width: calc(100% - 40px); } .nav-links { margin-left: 0; gap: 20px; } .nav-actions { gap: 16px; } .plan { padding: 24px 20px; } .plan-top { flex-wrap: wrap; } .badge { font-size: 8px; padding: 5px; } .grid { gap: 24px; } .faq { gap: 45px; } }
    @media (max-width: 680px) {
      .wrap { width: calc(100% - 36px); } .nav { height: 76px; gap: 15px; } .logo { font-size: 23px; } .nav-links { display: none; } .nav-actions { gap: 12px; } .nav-actions > a:first-child { display: none; } .nav-signup { padding: 10px 13px; font-size: 12px; }
      .hero { padding: 47px 0 30px; } h1 { font-size: 45px; letter-spacing: -1.8px; margin-top: 19px; } .hero p { font-size: 13px; max-width: 290px; margin-inline: auto; } .hero p br { display: none; } .billing { margin-top: 25px; }
      .plans { grid-template-columns: 1fr; gap: 18px; max-width: 420px; margin-inline: auto; } .plan { padding: 26px; } .plan-top { flex-wrap: nowrap; } .badge { font-size: 9px; padding: 6px 8px; } .desc { margin-bottom: 20px; } .price { font-size: 46px; } .feature-label { margin-top: 23px; } .plan ul { gap: 13px; }
      .features { margin-top: 42px; padding-block: 30px; } .grid { grid-template-columns: 1fr; gap: 26px; max-width: 350px; margin-inline: auto; } .feature p { max-width: none; } .section-kicker { margin-bottom: 28px; }
      .faq { grid-template-columns: 1fr; gap: 30px; padding: 42px 0 48px; } .faq h2 { font-size: 31px; } .faq h2 br { display: none; } summary { font-size: 12px; } .footer-inner { padding-block: 24px; flex-wrap: wrap; } footer p { margin: 0; } .footer-note { display: none; }
    }
    @media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } *, *::before, *::after { transition: none !important; } }
  </style>
</head>
<body>
  <svg class="svg-library" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
    <symbol id="book" viewBox="0 0 24 24"><path d="M12 5.5C9 3.7 5.6 3.3 2.5 4v15c3.1-.7 6.5-.3 9.5 1.5 3-1.8 6.4-2.2 9.5-1.5V4C18.4 3.3 15 3.7 12 5.5Z"/><path d="M12 5.5v15M6 8l3 .6M6 11.5l3 .6M15 8.6l3-.6M15 12.1l3-.6"/></symbol>
    <symbol id="check" viewBox="0 0 24 24"><path d="m5 12 4 4L19 6"/></symbol>
    <symbol id="minus" viewBox="0 0 24 24"><path d="M6 12h12"/></symbol>
    <symbol id="arrow" viewBox="0 0 24 24"><path d="M5 12h14m-5-5 5 5-5 5"/></symbol>
    <symbol id="leaf" viewBox="0 0 24 24"><path d="M19.5 3.5S7 1.5 5 10c-1.5 6 4 9 8.5 6S19.5 3.5 19.5 3.5ZM4 21 15 10"/></symbol>
    <symbol id="spark" viewBox="0 0 24 24"><path d="m12 2 2.8 7.2L22 12l-7.2 2.8L12 22l-2.8-7.2L2 12l7.2-2.8L12 2Z"/></symbol>
    <symbol id="team" viewBox="0 0 24 24"><circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 4v3"/></symbol>
    <symbol id="bolt" viewBox="0 0 24 24"><path d="m13 2-9 12h7l-1 8 10-13h-8l1-7Z"/></symbol>
    <symbol id="lock" viewBox="0 0 24 24"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/></symbol>
    <symbol id="sync" viewBox="0 0 24 24"><path d="M20 8a8 8 0 0 0-14-3L3 8m0-5v5h5M4 16a8 8 0 0 0 14 3l3-3m0 5v-5h-5"/></symbol>
    <symbol id="curve" viewBox="0 0 24 24"><path d="M21 5c-1 10-8 12-17 9m4-4-4 4 4 4"/></symbol>
  </svg>

  <header class="nav wrap">
    <a class="logo" href="#" aria-label="Marginalia home"><svg class="icon" aria-hidden="true"><use href="#book"/></svg>Marginalia</a>
    <nav class="nav-links" aria-label="Main navigation"><a href="#features">Features</a><a href="#pricing" aria-current="page">Pricing</a><a href="#faq">FAQs</a></nav>
    <div class="nav-actions"><a href="#">Log in</a><a class="nav-signup" href="#pricing">Start for free <span aria-hidden="true">↗</span></a></div>
  </header>

  <main class="wrap">
    <section class="hero" aria-labelledby="page-title">
      <span class="eyebrow">Room to think. Space to grow.</span>
      <h1 id="page-title">Good ideas deserve<br>a little <em>more space.</em></h1>
      <p>From your first note to your next big project, find a plan that fits.<br>Simple pricing. A clearer mind.</p>
      <div class="billing">
        <div class="toggle" role="group" aria-label="Billing period"><button type="button" aria-pressed="true" data-period="monthly">Monthly</button><button type="button" aria-pressed="false" data-period="yearly">Yearly</button></div>
        <span class="saving"><svg class="icon" aria-hidden="true"><use href="#curve"/></svg>Save 20%</span>
      </div>
    </section>

    <section class="plans" id="pricing" aria-label="Compare pricing plans">
      <article class="plan">
        <div class="plan-top"><div class="plan-name"><svg class="icon" aria-hidden="true"><use href="#leaf"/></svg><h2>Starter</h2></div></div>
        <p class="desc">A home for your everyday thoughts.</p>
        <div class="price">$0<small>/ month</small></div>
        <p class="billing-note">Free forever. Yours to make your own.</p>
        <a class="btn" href="#">Get started for free<svg class="icon" aria-hidden="true"><use href="#arrow"/></svg></a>
        <p class="feature-label">A little space to get started</p>
        <ul>
          <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Up to 100 notes</li>
          <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Sync across 2 devices</li>
          <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Basic search</li>
          <li class="unavailable"><svg class="icon" aria-hidden="true"><use href="#minus"/></svg>Offline access <span hidden>(not included)</span></li>
          <li class="unavailable"><svg class="icon" aria-hidden="true"><use href="#minus"/></svg>Shared notebooks <span hidden>(not included)</span></li>
        </ul>
      </article>
      <article class="plan popular">
        <div class="plan-top"><div class="plan-name"><svg class="icon" aria-hidden="true"><use href="#spark"/></svg><h2>Pro</h2></div><span class="badge">Most popular</span></div>
        <p class="desc">More room for everything on your mind.</p>
        <div class="price" aria-live="polite"><span data-price="pro">$8</span><small>/ month</small></div>
        <p class="billing-note" data-billing="pro">Billed monthly. Cancel anytime.</p>
        <a class="btn" href="#">Try Pro for free<svg class="icon" aria-hidden="true"><use href="#arrow"/></svg></a>
        <p class="feature-label">Everything in Starter, and more</p>
        <ul>
          <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Unlimited notes</li>
          <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Sync across unlimited devices</li>
          <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Full-text search inside PDFs</li>
          <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Offline access</li>
          <li class="unavailable"><svg class="icon" aria-hidden="true"><use href="#minus"/></svg>Shared notebooks <span hidden>(not included)</span></li>
        </ul>
      </article>
      <article class="plan">
        <div class="plan-top"><div class="plan-name"><svg class="icon" aria-hidden="true"><use href="#team"/></svg><h2>Team</h2></div></div>
        <p class="desc">Great things start with shared ideas.</p>
        <div class="price" aria-live="polite"><span data-price="team">$14</span><small>/ user / month</small></div>
        <p class="billing-note" data-billing="team">Billed monthly. Grow at your own pace.</p>
        <a class="btn" href="#">Get started with Team<svg class="icon" aria-hidden="true"><use href="#arrow"/></svg></a>
        <p class="feature-label">Everything in Pro, plus</p>
        <ul>
          <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Shared notebooks</li>
          <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Admin controls</li>
          <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Priority support</li>
          <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Single sign-on (SSO)</li>
          <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Unlimited notes and devices</li>
        </ul>
      </article>
    </section>
    <p class="reassurance"><svg class="icon" aria-hidden="true"><use href="#lock"/></svg>14 days of Pro, on us. No credit card required.</p>

    <section class="features" id="features" aria-labelledby="features-title">
      <h2 class="section-kicker" id="features-title">Thoughtfully made. Whichever plan you choose.</h2>
      <div class="grid">
        <div class="feature"><svg class="icon" aria-hidden="true"><use href="#bolt"/></svg><div><h3>Less waiting. More thinking.</h3><p>Fast, effortless search that keeps up with the way your mind works.</p></div></div>
        <div class="feature"><svg class="icon" aria-hidden="true"><use href="#lock"/></svg><div><h3>Your thoughts stay yours.</h3><p>Encrypted and protected. A private space for everything that matters to you.</p></div></div>
        <div class="feature"><svg class="icon" aria-hidden="true"><use href="#sync"/></svg><div><h3>Right where you left off.</h3><p>Notes that follow you from desk to doorstep, seamlessly synced across devices.</p></div></div>
      </div>
    </section>

    <section class="faq" id="faq" aria-labelledby="faq-title">
      <div class="faq-intro"><span class="eyebrow">A few more things</span><h2 id="faq-title">Good questions.<br>Simple answers.</h2><p>A little clarity before you get started.</p></div>
      <div class="questions">
        <details open><summary>Can I cancel anytime?</summary><p>Of course. Cancel your subscription at any time, no questions asked.</p></details>
        <details><summary>Is there a free trial for Pro?</summary><p>Yes. Try Pro free for 14 days, with no credit card required.</p></details>
        <details><summary>Do you offer student discounts?</summary><p>Yes! Students get 50% off Pro with a valid school email.</p></details>
      </div>
    </section>
  </main>

  <footer><div class="footer-inner wrap"><a class="logo" href="#" aria-label="Marginalia home"><svg class="icon" aria-hidden="true"><use href="#book"/></svg>Marginalia</a><span class="footer-note">A quieter place for your mind.</span><p>© 2026 Marginalia Inc. All rights reserved.</p></div></footer>

  <script>
    const billingOptions = document.querySelectorAll('"'[data-period]');
    const prices = {
      monthly: { pro: '"'$8'"', team: '"'$14'"' },
      yearly: { pro: '"'$6.40'"', team: '"'$11.20'"' }
    };
    billingOptions.forEach(button => {
      button.addEventListener('click', () => {
        const period = button.dataset.period;
        billingOptions.forEach(option => option.setAttribute('aria-pressed', String(option === button)));
        ['pro', 'team'].forEach(plan => {
          document.querySelector("'`[data-price="${plan}"]`).textContent = prices[period][plan];
          document.querySelector(`[data-billing="${plan}"]`).textContent = period === '"'yearly'
            ? (plan === 'pro' ? '"'$76.80 billed yearly. Save 20%.'"' : '"'$134.40 per user billed yearly. Save 20%.'"')
            : (plan === 'pro' ? 'Billed monthly. Cancel anytime.' : 'Billed monthly. Grow at your own pace.');
        });
      });
    });
  </script>
</body>
</html>
EOF"

